   const cfg = persona ?? getConfig().persona;
   const isPrivate = skillContext?.kind === 'private';
+  const usePlayful = !isPrivate && usesPlayfulExpression(getConfig(), {
+    kind: 'group',
+    systemPromptOverride: cfg.systemPromptOverride,
+  });
@@
-    antiAiFlavor(),
-    '',
-    subjectivity(),
-    '',
-    isPrivate ? [
+    usePlayful ? playfulExpressionSection() : antiAiFlavor(),
+    '',
+    usePlayful ? '' : subjectivity(),
+    '',
+    isPrivate ? [
       '【私聊的相处方式】',
@@
-    isPrivate ? '' : speakOrNot(cfg.participation),
+    isPrivate ? '' : (usePlayful ? participationOnly(cfg.participation) : speakOrNot(cfg.participation)),
     '',
-    isPrivate ? '' : notAQueue(),
+    isPrivate ? '' : (usePlayful ? '' : notAQueue()),
     '',
     isPrivate ? '【私聊节奏】...' : humanRhythm(),
@@
-    isPrivate ? '' : notModerator(),
+    isPrivate ? '' : (usePlayful ? '' : notModerator()),
@@
   if (getConfig().naturalChat?.enabled === true) parts.push('', naturalConversationRules());
@@
 }
+
+// 仅在 playful 模式下保留参与度说明行，去掉“该说/不该说”其余负向句。
+function participationOnly(level) {
+  return `【参与度】${participationText(level)}`;
+}
```

说明：
- `antiAiFlavor` 整段被 playful 段替换；`subjectivity`、`speakOrNot`、`notAQueue`、`notModerator` 也整段替换为空或仅参与度行——这是**唯一**要动的重叠段；`humanRhythm` 的“停顿/分条”仍保留（属节奏而非风格）。
- `naturalConversationRules` **整段保留**，只由 playful 段自然覆盖其“不用故意装傻”的语义（不在 profile 里再写一次）。
- `systemPromptOverride` 分支不动，仍走 `naturalConversationRules`。
- `NORMAL_ROLE_CARD`、`securityRules`、`toolProtocol`、`roleBoundaryRules`、`memoryRules`、`qqSceneRules`、`reportBan`、`stickerRules` 一字不动。

**对照/边界测试草案（可审阅，不执行）**：

1. `usesPlayfulExpression` 真值表：`{sb.enabled, phase2.enabled, expressionProfile, kind, override}` 全组合，断言任一不满足即为 false。
2. legacy 默认：`expressionProfile` 未设时，`expressionProfileOf` 返回 `'legacy'`，系统提示字节级与现状一致（可用快照对比）。
3. playful 生效：普通群聊 + playful 时，系统提示包含 `【熟人间的表达：playful-v1】`，且不包含 `【反 AI 味】` 标题字、不包含 `不用故意装傻`（来自被替换段），仍包含 `naturalConversationRules` 的其它条款标题首句。
4. 私聊/覆盖边界：`kind='private'` 或 `systemPromptOverride` 非空时，`usesPlayfulExpression` 返回 false。
5. 安全不变：playful 生效前后，`securityRules`/`toolProtocol`/`roleBoundaryRules`/`memoryRules`/`qqSceneRules` 段字符数一致。
6. 不产生默认台词：`playfulExpressionSection()` 不含“草”、“反弹”、“猫粮被你扣光了”等示例作为要求模型必填的输出（仅作为许可示例出现，且明确“不新增默认台词”）。
7. 字符数：`playfulExpressionSection().length` 落在 `[500, 850]`。
8. 被叫停：单测提示词断言“立即收起玩笑给实际回答”存在，但**不**依赖 `DIRECT_STOP` 正则——这正是与 Gemini 原方案的分歧点。

### B. DeepSeek 侧：`qq-agent/src/social-knowledge-context.mjs` 完整新模块

要求：函数接受 `runtime/chatKey/entries/store/roleScope`；owner 由调用方算（`socialFocusOwner`）传入避免循环 import；current 保留原 owner directText；linked-v1 额外只取 owner 真实 reply.mid 指向的、本群 `store.findByMid` 查到、`self===true`、`personaScope` 严格等于当前**完整 scope**、非 `modelExcluded`、文本长度有上限的猫自己父消息，最多 2 条、总 400 字。返回 `{query, ownTextChars, linkedCount, linkedChars, reason}` 等有限元数据，**原文不入统计**；正文合计不超 600 字。

```js
// qq-agent/src/social-knowledge-context.mjs
// 默认关闭的 linked-v1 上下文补全实验。只决定“喂给检索的 query 从哪来”，
// 不改检索算法、不改 BM25 门槛、不加 feedback 证据。
//
// 边界：
// - current 模式完全等价于原 knowledgeHint 的 owner directText 查询。
// - linked-v1 额外只取本次 owner 的 reply.mid 指向的、本群 store 查到、
//   self===true、personaScope 严格等于当前完整 scope、非 modelExcluded、
//   文本有上限的猫父消息，最多 2 条、总 400 字。
// - 不读消息内伪造引用字符串；不用任意环境历史；不跨群；不读其他 AI 发言；
//   不用图片/拍一拍合成描述当父消息正文（父消息只有 text）。
// - 引用原文不进替代反馈证据；调用方不得把 linked 文本交给 feedback。

const DEFAULT_MAX_LINKED = 2;
const DEFAULT_MAX_LINKED_CHARS = 400;
const DEFAULT_MAX_TOTAL_CHARS = 600;
const HARD_TEXT_CAP = 200; // 单条父消息文本硬上限，超出截断

export function knowledgeContextModeOf(config) {
  try {
    const m = config?.socialBehavior?.phase2?.knowledgeContext;
    return m === 'linked-v1' ? 'linked-v1' : 'current';
  } catch {
    return 'current';
  }
}

/**
 * @param {object} args
 * @param {object} args.runtime        需有 getConfig / roleIdentity(scope) 提供方
 * @param {string} args.chatKey
 * @param {object[]} args.entries      本批触发消息
 * @param {object} args.store          需有 findByMid(chatKey, mid)
 * @param {string|null} args.roleScope 当前完整 roleScope（由调用方算）
 * @param {string|null} [args.owner]   由调用方算的 owner（socialFocusOwner 结果）
 */
export function buildKnowledgeQuery({
  runtime,
  chatKey,
  entries,
  store,
  roleScope,
  owner,
}) {
  const cfg = runtime?.getConfig?.() ?? {};
  const mode = knowledgeContextModeOf(cfg);
  const list = Array.isArray(entries) ? entries : [];

  const ownEntries = owner
    ? list.filter(
        (e) =>
          String(e?.senderId) === String(owner) &&
          isModelAllowed(e)
      )
    : [];

  const rawOwn = ownEntries
    .map((e) => (typeof e?.directText === 'string' ? e.directText : ''))
    .filter(Boolean)
    .join('\n');

  // 正文先不截：调用方当前行为是 slice(0,600)，这里保持一致语义，
  // 只在下方统一裁到 MAX_TOTAL。
  const ownText = rawOwn;

  if (!owner) {
    return {
      query: '',
      mode,
      ownTextChars: 0,
      linkedCount: 0,
      linkedChars: 0,
      reason: 'no_owner',
    };
  }
  if (!ownText.trim()) {
    return {
      query: '',
      mode,
      ownTextChars: 0,
      linkedCount: 0,
      linkedChars: 0,
      reason: 'no_own_text',
    };
  }

  if (mode !== 'linked-v1') {
    const query = ownText.slice(0, DEFAULT_MAX_TOTAL_CHARS);
    return {
      query,
      mode,
      ownTextChars: ownText.length,
      linkedCount: 0,
      linkedChars: 0,
      reason: 'current',
    };
  }

  // ── linked-v1 ──
  const linked = [];
  let linkedChars = 0;
  const dropped = { no_store: 0, not_parent: 0, not_self: 0, scope: 0, excluded: 0, empty: 0, cap: 0 };

  const mids = [];
  for (const e of ownEntries) {
    const mid = e?.reply?.mid;
    if (mid != null && !mids.includes(mid)) mids.push(mid);
  }

  if (!store || typeof store.findByMid !== 'function') {
    dropped.no_store = mids.length;
  } else {
    for (const mid of mids) {
      if (linked.length >= DEFAULT_MAX_LINKED) break;
      let parent = null;
      try {
        parent = store.findByMid(chatKey, mid);
      } catch {
        parent = null;
      }
      if (!parent) { dropped.not_parent++; continue; }
      if (parent.self !== true) { dropped.not_self++; continue; }
      // 严格完整 scope 相等；任何缺省/空值都拒绝
      if (
        typeof roleScope !== 'string' ||
        !roleScope ||
        parent.personaScope !== roleScope
      ) {
        dropped.scope++;
        continue;
      }
      if (parent.modelExcluded === true) { dropped.excluded++; continue; }
      const text = typeof parent.text === 'string' ? parent.text : '';
      if (!text.trim()) { dropped.empty++; continue; }
      const clipped = text.slice(0, HARD_TEXT_CAP);
      if (linkedChars + clipped.length > DEFAULT_MAX_LINKED_CHARS) {
        // 放不下就跳过，不半截塞进去
        dropped.cap++;
        continue;
      }
      linked.push(clipped);
      linkedChars += clipped.length;
    }
  }

  // 正文保留优先：ownText 先占满，再拼 linked；总不超 600。
  let query = ownText.slice(0, DEFAULT_MAX_TOTAL_CHARS);
  let appended = 0;
  for (const t of linked) {
    if (query.length + 1 + t.length > DEFAULT_MAX_TOTAL_CHARS) break;
    query += '\n' + t;
    appended++;
  }
  const appendedChars = query.length - Math.min(ownText.length, DEFAULT_MAX_TOTAL_CHARS);

  return {
    query,
    mode,
    ownTextChars: ownText.length,
    linkedCount: appended,
    linkedChars: appendedChars,
    reason:
      mode === 'linked-v1' && appended === 0
        ? `linked_empty:${Object.entries(dropped)
            .filter(([, v]) => v > 0)
            .map(([k, v]) => `${k}=${v}`)
            .join(',') || 'no_reply_mid'}`
        : 'linked-v1',
  };
}

function isModelAllowed(e) {
  return e?.modelExcluded !== true;
}
```

（`isModelAllowed` 只做 `modelExcluded` 检查；`input-guard` 的 `modelInputAllowed` 已在 `social-runtime._admit` 上游把过关，避免此模块重复 import。）**注意：`senderId==='self'` 与 `store.appendSelf` 的父消息 `senderId` 语义不同——本模块只信任 `store.findByMid` 返回的 `self===true` 字段，不靠 `senderId` 猜。**

